import{_ as r,C as i,c as l,o as c,a3 as n,G as a,j as s,a as o}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"First steps","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/maintenance/get-started/first-steps.md","filePath":"master/supply-chain/maintenance/get-started/first-steps.md","lastUpdated":1792041590000}'),d={name:"master/supply-chain/maintenance/get-started/first-steps.md"};function g(h,e,p,m,u,_){const t=i("ImagePopup");return c(),l("div",null,[e[0]||(e[0]=n('<h1 id="first-steps" tabindex="-1">First steps <a class="header-anchor" href="#first-steps" aria-label="Permalink to &quot;First steps&quot;">​</a></h1><p>This tutorial takes you through one full maintenance job. You set up a team and a category, add a machine, report a fault, repair it, and then schedule the same care to repeat each month. Every step uses the same machine, the <strong>Hydraulic Press 200T</strong>.</p><blockquote><p><strong>In simple words:</strong> Build the press, break the press, fix the press, then make sure it is looked after every month.</p></blockquote><p>Think of the tutorial as a map. Each step gives a short instruction and links to the page that explains it in depth.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Setup (1-3)  →  Equipment (4)  →  Request (5-7)  →  Calendar (8)  →  Preventive (9)</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">Before you start</p><p>This tutorial uses a technician named Linda Ndlovu, a user named Sales Admin and a vendor named Consolidated Components. Use your own users and vendor if these do not exist. Create users in <a href="./../../../general-settings/users/manage-users.html">Manage users</a> and vendors in <a href="./../../../getting-started/contacts/contacts.html">Contacts</a>.</p></div><h2 id="_1-check-the-stages-and-the-team" tabindex="-1">1. Check the stages and the team <a class="header-anchor" href="#_1-check-the-stages-and-the-team" aria-label="Permalink to &quot;1. Check the stages and the team&quot;">​</a></h2><p>Open <code>Maintenance → Configurations → Stages</code>. The list shows <strong>New Request</strong>, <strong>In Progress</strong>, <strong>Repaired</strong> and <strong>Scrap</strong>. <strong>Repaired</strong> and <strong>Scrap</strong> have a green tick under <strong>Done</strong>. Then open <code>Maintenance → Configurations → Teams</code>. The team <strong>Internal Maintenance</strong> is there.</p>',8)),a(t,{src:"/images1/maintenance/ft_check_stages.png",alt:"Maintenance Stages list showing New Request, In Progress, Repaired and Scrap, with green Done ticks on Repaired and Scrap"}),e[1]||(e[1]=n('<p><strong>Behind the scenes:</strong> the Done flag decides when a request counts as closed. See <a href="./../setup/stages.html">Stages</a>.</p><h2 id="_2-create-a-category" tabindex="-1">2. Create a category <a class="header-anchor" href="#_2-create-a-category" aria-label="Permalink to &quot;2. Create a category&quot;">​</a></h2><p>Open <code>Maintenance → Configurations → Categories</code> and click <strong>New Category</strong>.</p><ul><li><strong><em>Name:</em></strong> <code>Packaging Machines</code></li><li><strong><em>Responsible:</em></strong> <code>Linda Ndlovu</code></li></ul><p>Click <strong>Create</strong>. The notification <strong>Category created</strong> appears and the category opens on its view page.</p>',5)),a(t,{src:"/images1/maintenance/ft_category.png",alt:"Create Equipment Category form filled with Packaging Machines and Responsible Linda Ndlovu"}),e[2]||(e[2]=n('<p><strong>Behind the scenes:</strong> Linda becomes the default technician for requests on this kind of machine. See <a href="./../setup/equipment-categories.html">Equipment categories</a>.</p><h2 id="_3-create-a-team" tabindex="-1">3. Create a team <a class="header-anchor" href="#_3-create-a-team" aria-label="Permalink to &quot;3. Create a team&quot;">​</a></h2><p>Open <code>Maintenance → Configurations → Teams</code> and click <strong>New Team</strong>.</p><ul><li><strong><em>Name:</em></strong> <code>Electrical Maintenance Team</code></li><li><strong><em>Team Members:</em></strong> <code>Linda Ndlovu</code></li></ul><p>Click <strong>Create</strong>.</p>',5)),a(t,{src:"/images1/maintenance/ft_team.png",alt:"Create Maintenance Team window with Electrical Maintenance Team and member Linda Ndlovu"}),e[3]||(e[3]=n('<p>See <a href="./../setup/maintenance-teams.html">Maintenance teams</a>.</p><h2 id="_4-add-the-equipment" tabindex="-1">4. Add the equipment <a class="header-anchor" href="#_4-add-the-equipment" aria-label="Permalink to &quot;4. Add the equipment&quot;">​</a></h2><p>Open <code>Equipment</code> and click <strong>New Equipment</strong>. Fill in the form.</p><ul><li><strong><em>Name:</em></strong> <code>Hydraulic Press 200T</code></li><li><strong><em>Vendor:</em></strong> an existing vendor, such as <code>Consolidated Components</code></li><li><strong><em>Model:</em></strong> <code>HP-200</code></li><li><strong><em>Serial Number:</em></strong> <code>HP-200-2026-001</code></li><li><strong><em>Cost:</em></strong> <code>18500</code></li><li><strong><em>Warranty Expiration Date:</em></strong> <code>2028-06-30</code></li><li><strong><em>Equipment Category:</em></strong> <code>Packaging Machines</code>. The <strong>Technician</strong> fills with the category&#39;s <strong>Responsible</strong>, Linda Ndlovu.</li><li><strong><em>Maintenance Team:</em></strong> <code>Electrical Maintenance Team</code></li><li><strong><em>Technician:</em></strong> <code>Linda Ndlovu</code></li><li><strong><em>Owner:</em></strong> <code>Sales Admin</code></li><li><strong><em>Used in location:</em></strong> <code>Workshop A</code></li><li><strong><em>Expected Mean Time Between Failure:</em></strong> <code>90</code></li></ul><p>Click <strong>Create</strong>. The equipment opens on its view page.</p>',5)),a(t,{src:"/images1/maintenance/ft_equipment.png",alt:"Create Equipment form filled for Hydraulic Press 200T with category Packaging Machines, team Electrical Maintenance Team, technician Linda Ndlovu and warranty 30 June 2028"}),e[4]||(e[4]=n('<p>See <a href="./../equipment/add-equipment.html">Add equipment</a>.</p><h2 id="_5-report-the-problem" tabindex="-1">5. Report the problem <a class="header-anchor" href="#_5-report-the-problem" aria-label="Permalink to &quot;5. Report the problem&quot;">​</a></h2><p>The press is leaking oil. Open <code>Maintenance → Maintenance Requests</code> and click <strong>New Maintenance Request</strong>.</p><ul><li><strong><em>Request:</em></strong> <code>Hydraulic press oil leak</code></li><li><strong><em>Equipment:</em></strong> <code>Hydraulic Press 200T</code></li></ul><p>When you pick the equipment, Aureus fills <strong>Category</strong>, <strong>Team</strong>, <strong>Responsible</strong> and <strong>Company</strong> for you. <strong>Request Date</strong> stays on today. Leave <strong>Maintenance Type</strong> on <strong>Corrective</strong>. Do not click <strong>Create</strong> yet. Go on to step 6.</p>',5)),a(t,{src:"/images1/maintenance/ft_request_equipment.png",alt:"Maintenance request form with Hydraulic press oil leak and Hydraulic Press 200T, Category Packaging Machines, Team Electrical Maintenance Team and Responsible Linda Ndlovu filled"}),e[5]||(e[5]=n('<p><strong>Behind the scenes:</strong> the values come from the equipment. You can still change them on this request. See <a href="./../requests/create-request.html">Create a maintenance request</a>.</p><h2 id="_6-assign-and-schedule" tabindex="-1">6. Assign and schedule <a class="header-anchor" href="#_6-assign-and-schedule" aria-label="Permalink to &quot;6. Assign and schedule&quot;">​</a></h2><p>In the <strong>Settings</strong> card on the right, set:</p><ul><li><strong><em>Responsible:</em></strong> <code>Linda Ndlovu</code></li><li><strong><em>Scheduled Date:</em></strong> a date in the near future, for example <code>Oct 14, 2026 09:00</code></li><li><strong><em>Duration:</em></strong> <code>02:00</code></li><li><strong><em>Priority:</em></strong> <code>2</code>. Use 0 for normal work and 1 to 3 for work that needs attention first.</li></ul><p>Click <strong>Create</strong>. The notification <strong>Maintenance request created</strong> appears and the request opens on its view page in the stage <strong>New Request</strong>.</p>',5)),a(t,{src:"/images1/maintenance/ft_request_settings.png",alt:"Settings card with Electrical Maintenance Team, Linda Ndlovu, scheduled date Oct 14, 2026 09:00, duration 02:00 and priority 2"}),e[6]||(e[6]=n('<h2 id="_7-move-it-to-repaired" tabindex="-1">7. Move it to Repaired <a class="header-anchor" href="#_7-move-it-to-repaired" aria-label="Permalink to &quot;7. Move it to Repaired&quot;">​</a></h2><p>Open the request and click <strong>Edit</strong>. The stage bar on the view page is read only. Click <strong>In Progress</strong> on the stage bar when Linda starts, then click <strong>Save changes</strong>. When the leak is fixed, click <strong>Repaired</strong>, then click <strong>Save changes</strong>. The notification <strong>Maintenance request updated</strong> appears.</p>',2)),a(t,{src:"/images1/maintenance/ft_stage_repaired.png",alt:"Edit page of Hydraulic press oil leak with Repaired highlighted in the stage bar"}),e[7]||(e[7]=n('<p><strong>Behind the scenes:</strong> <strong>Repaired</strong> has the Done flag, so the request is closed. It moves from the <strong>To Do</strong> tab to the <strong>Done</strong> tab. See <a href="./../requests/process-request.html">Process a request</a>.</p><h2 id="_8-see-it-on-the-calendar" tabindex="-1">8. See it on the calendar <a class="header-anchor" href="#_8-see-it-on-the-calendar" aria-label="Permalink to &quot;8. See it on the calendar&quot;">​</a></h2><p>Open <code>Maintenance → Maintenance Calendar</code>. The request shows on its scheduled day, 14 October 2026. It is green because its stage is done. Open jobs are blue. The request is on 14 October, so the grid shows it in the October 2026 month.</p>',3)),a(t,{src:"/images1/maintenance/ft_calendar.png",alt:"Maintenance Calendar October 2026 month grid with Hydraulic press oil leak in green on Oct 14"}),e[8]||(e[8]=n('<p>See <a href="./../calendar/maintenance-calendar.html">Maintenance calendar</a>.</p><h2 id="_9-set-up-the-monthly-preventive-job" tabindex="-1">9. Set up the monthly preventive job <a class="header-anchor" href="#_9-set-up-the-monthly-preventive-job" aria-label="Permalink to &quot;9. Set up the monthly preventive job&quot;">​</a></h2><p>Fixing faults is not enough. Create a second request to look after the press before it breaks.</p><ol><li>Click <strong>New Maintenance Request</strong>.</li><li><strong><em>Request:</em></strong> <code>Monthly lubrication, Hydraulic Press 200T</code>.</li><li><strong><em>Equipment:</em></strong> <code>Hydraulic Press 200T</code>.</li><li><strong><em>Maintenance Type:</em></strong> <strong>Preventive</strong>.</li><li>Tick <strong>Recurrent</strong>.</li><li><strong><em>Repeat Every:</em></strong> <code>1</code>, <code>Months</code>, <code>Forever</code>.</li><li>Set <strong>Scheduled Date</strong> to <code>Oct 20, 2026 09:00</code> and <strong>Duration</strong> to <code>01:00</code>. Click <strong>Create</strong>.</li></ol>',4)),a(t,{src:"/images1/maintenance/ft_preventive_form.png",alt:"Monthly lubrication request with Preventive selected, Recurrent ticked and Repeat Every set to 1 Months Forever"}),e[9]||(e[9]=s("p",null,[o("Open the request, click "),s("strong",null,"Edit"),o(", choose "),s("strong",null,"Repaired"),o(" and click "),s("strong",null,"Save changes"),o(". Aureus creates a copy in "),s("strong",null,"New Request"),o(", scheduled one month after the original: "),s("strong",null,"Nov 20, 2026 09:00"),o(".")],-1)),a(t,{src:"/images1/maintenance/ft_preventive_copy.png",alt:"Request list showing the Repaired Monthly lubrication request and its new copy in New Request scheduled Nov 20, 2026 09:00"}),e[10]||(e[10]=n('<p><strong>Behind the scenes:</strong> the copy keeps the time and duration, and it also creates an activity for the responsible person, so it shows up in their to-do list. See <a href="./../requests/preventive-maintenance.html">Preventive maintenance</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You now know the full loop. Use the request list to see all jobs at a glance. See <a href="./../requests/request-list.html">Request list</a>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../">Maintenance overview</a></li><li><a href="./../setup/">Setup</a></li><li><a href="./../requests/process-request.html">Process a request</a></li><li><a href="./../equipment/manage-equipment.html">Manage equipment</a></li></ul>',4))])}const q=r(d,[["render",g]]);export{f as __pageData,q as default};
